/**
 * HarnessRouter — a JavaScript client for any server that speaks the Unified Harness Protocol.
 *
 * A harness is a configured agent: a runtime, a model, instructions and limits. A task is one run
 * of it. This client sends work, follows it while it happens, continues the conversation, cancels
 * it, and collects the files it produced.
 *
 * It is a UHP client, not a HarnessRouter client — it works against the open-source server, the
 * hosted one, or any third implementation that passes the conformance suite.
 *
 * Spec: https://github.com/HarnessRouter/harnessrouter/tree/main/protocol
 */

import {
  ENDPOINTS,
  PROTOCOL_VERSION,
  VERSION_HEADER,
  isTerminal,
} from 'unifiedharnessprotocol';
import {
  TaskAccumulator,
  artifacts,
  backoffMs,
  idempotencyKey,
  isRetryable,
  outputText,
  readEventStream,
} from 'harnessclientprotocol';

/**
 * A failed request, carrying the server's own error envelope.
 *
 * The failure of a *request* is this. The failure of a *task* is a response object with
 * `status: "failed"` and HTTP 200 — a different event, and deliberately not conflated.
 */
export class UhpError extends Error {
  constructor({ status, type, code, message, param = null, detail = null, requestId = null }) {
    super(message || `${type || 'error'} (${code || status})`);
    this.name = 'UhpError';
    this.status = status;
    this.type = type;
    this.code = code;
    this.param = param;
    this.detail = detail;
    this.requestId = requestId;
  }

  /** Whether trying this again could plausibly work. */
  get retryable() {
    return isRetryable({ code: this.code, type: this.type, status: this.status });
  }
}

const DEFAULT_TIMEOUT_MS = 15 * 60 * 1000; // agent tasks run for minutes; a 30s timeout kills healthy work

export class HarnessRouter {
  /**
   * @param {object} options
   * @param {string} options.baseUrl   Server root, e.g. `http://localhost:3000`
   * @param {string} [options.apiKey]  Bearer token
   * @param {string} [options.version] Protocol version to request; omit to take the server's default
   * @param {number} [options.timeoutMs]
   * @param {number} [options.maxRetries]
   * @param {typeof fetch} [options.fetch]
   */
  constructor({
    baseUrl,
    apiKey = '',
    version = PROTOCOL_VERSION,
    timeoutMs = DEFAULT_TIMEOUT_MS,
    maxRetries = 2,
    fetch: fetchImpl,
  } = {}) {
    if (!baseUrl) throw new TypeError('baseUrl is required');
    this.baseUrl = String(baseUrl).replace(/\/+$/, '');
    this.apiKey = apiKey;
    this.version = version;
    this.timeoutMs = timeoutMs;
    this.maxRetries = maxRetries;
    this.fetch = fetchImpl || globalThis.fetch;
    if (!this.fetch) throw new TypeError('no fetch available; pass one in options.fetch');
  }

  headers(extra = {}) {
    const headers = { accept: 'application/json' };
    if (this.apiKey) headers.authorization = `Bearer ${this.apiKey}`;
    if (this.version) headers[VERSION_HEADER] = this.version;
    // An explicit `undefined` removes a header — that is how discovery drops the bearer token.
    for (const [name, value] of Object.entries(extra)) {
      if (value === undefined) delete headers[name];
      else headers[name] = value;
    }
    return headers;
  }

  async request(method, path, { body, headers, retry = true, signal } = {}) {
    let attempt = 0;
    for (;;) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), this.timeoutMs);
      if (signal) signal.addEventListener('abort', () => controller.abort(), { once: true });
      let res;
      try {
        res = await this.fetch(`${this.baseUrl}${path}`, {
          method,
          headers: this.headers({
            ...(body === undefined ? {} : { 'content-type': 'application/json' }),
            ...headers,
          }),
          body: body === undefined ? undefined : JSON.stringify(body),
          signal: controller.signal,
        });
      } finally {
        clearTimeout(timer);
      }

      if (res.ok) {
        if (res.status === 204) return null;
        const text = await res.text();
        return text ? JSON.parse(text) : null;
      }

      const error = await toError(res);
      if (retry && attempt < this.maxRetries && error.retryable) {
        const retryAfter = Number(res.headers.get('retry-after'));
        await sleep(backoffMs(attempt, { retryAfterSeconds: Number.isFinite(retryAfter) ? retryAfter : null }));
        attempt += 1;
        continue;
      }
      throw error;
    }
  }

  // ---- discovery -------------------------------------------------------------------------

  /** What this server is and what it can do. Served without a token, by design. */
  discover() {
    return this.request('GET', ENDPOINTS.discovery, { headers: { authorization: undefined } });
  }

  /** Every configured harness in your scope. May legitimately be empty. */
  async harnesses() {
    const body = await this.request('GET', ENDPOINTS.harnesses);
    return body?.harnesses ?? [];
  }

  harness(harnessId) {
    return this.request('GET', ENDPOINTS.harness(harnessId));
  }

  models() {
    return this.request('GET', ENDPOINTS.models);
  }

  /** Models this harness can actually run right now — `available` is computed, not asserted. */
  harnessModels(harnessId) {
    return this.request('GET', ENDPOINTS.harnessModels(harnessId));
  }

  // ---- tasks -----------------------------------------------------------------------------

  /**
   * Run a task and wait for the result.
   *
   * An `Idempotency-Key` is attached automatically: a retry that runs an agent twice is the most
   * damaging mistake a UHP client can make, and the cost of preventing it is one header.
   */
  async run(input, options = {}) {
    const { harnessId, key = idempotencyKey(), signal, ...rest } = options;
    const body = buildTaskBody(input, harnessId, rest, false);
    return this.request('POST', ENDPOINTS.responses, {
      body,
      headers: { 'idempotency-key': key },
      retry: false, // a task that may have started is not safe to fire again on our own initiative
      signal,
    });
  }

  /**
   * Run a task and yield events as they happen.
   *
   * ```js
   * for await (const event of client.stream('Summarise README.md', { harnessId })) {
   *   if (event.type === 'response.output_text.delta') process.stdout.write(event.delta);
   * }
   * ```
   */
  async *stream(input, options = {}) {
    const { harnessId, key = idempotencyKey(), signal, ...rest } = options;
    const body = buildTaskBody(input, harnessId, rest, true);
    const res = await this.fetch(`${this.baseUrl}${ENDPOINTS.responses}`, {
      method: 'POST',
      headers: this.headers({
        'content-type': 'application/json',
        accept: 'text/event-stream',
        'idempotency-key': key,
      }),
      body: JSON.stringify(body),
      signal,
    });
    if (!res.ok) throw await toError(res);
    yield* readEventStream(res);
  }

  /**
   * Run a task, follow the stream, and return the finished result.
   *
   * `onEvent` sees every event on the way past, so a caller can render progress without having
   * to reimplement accumulation.
   */
  async collect(input, options = {}) {
    const { onEvent, ...rest } = options;
    const accumulator = new TaskAccumulator();
    for await (const event of this.stream(input, rest)) {
      accumulator.add(event);
      if (onEvent) onEvent(event);
    }
    return accumulator;
  }

  /** Continue the conversation that produced `responseId`, in the same working directory. */
  continue(responseId, input, options = {}) {
    return this.run(input, { ...options, previousResponseId: responseId });
  }

  getResponse(responseId) {
    return this.request('GET', ENDPOINTS.response(responseId));
  }

  inputItems(responseId) {
    return this.request('GET', ENDPOINTS.responseInputItems(responseId));
  }

  /** Ask for a stop. Cancelling twice is not an error, and the session stays continuable. */
  cancel(responseId) {
    return this.request('POST', ENDPOINTS.responseCancel(responseId));
  }

  /** Delete the stored response. This does not stop a running task — that is `cancel`. */
  deleteResponse(responseId) {
    return this.request('DELETE', ENDPOINTS.response(responseId));
  }

  /** Poll a task to a terminal state, for a client that lost its stream. */
  async wait(responseId, { intervalMs = 2000, timeoutMs = this.timeoutMs } = {}) {
    const deadline = Date.now() + timeoutMs;
    for (;;) {
      const response = await this.getResponse(responseId);
      if (isTerminal(response?.status)) return response;
      if (Date.now() > deadline) throw new Error(`response ${responseId} did not finish within ${timeoutMs}ms`);
      await sleep(intervalMs);
    }
  }

  // ---- sessions --------------------------------------------------------------------------

  sessions({ limit, cursor, harness } = {}) {
    const query = new URLSearchParams();
    if (limit != null) query.set('limit', String(limit));
    if (cursor) query.set('cursor', cursor);
    if (harness) query.set('harness', harness);
    const suffix = query.toString() ? `?${query}` : '';
    return this.request('GET', `${ENDPOINTS.sessions}${suffix}`);
  }

  session(sessionId) {
    return this.request('GET', ENDPOINTS.session(sessionId));
  }

  /** The ordered task history of a session, for rebuilding a transcript you did not store. */
  turns(sessionId) {
    return this.request('GET', ENDPOINTS.sessionTurns(sessionId));
  }

  async sessionFiles(sessionId) {
    const body = await this.request('GET', ENDPOINTS.sessionFiles(sessionId));
    return body?.files ?? [];
  }

  cancelSession(sessionId) {
    return this.request('POST', ENDPOINTS.sessionCancel(sessionId));
  }

  deleteSession(sessionId) {
    return this.request('DELETE', ENDPOINTS.sessionDelete(sessionId));
  }

  // ---- files -----------------------------------------------------------------------------

  /** Upload a file once and reference it by id, instead of base64-inflating it through retries. */
  async uploadFile(file, filename) {
    const form = new FormData();
    form.append('file', file, filename);
    const res = await this.fetch(`${this.baseUrl}${ENDPOINTS.files}`, {
      method: 'POST',
      headers: this.headers(),
      body: form,
    });
    if (!res.ok) throw await toError(res);
    return res.json();
  }

  /** Download an artifact. Returns the raw `Response` so a caller chooses how to consume it. */
  async downloadFile(containerId, fileId) {
    const res = await this.fetch(`${this.baseUrl}${ENDPOINTS.fileContent(containerId, fileId)}`, {
      headers: this.headers({ accept: '*/*' }),
    });
    if (!res.ok) throw await toError(res);
    return res;
  }
}

function buildTaskBody(input, harnessId, rest, stream) {
  const { previousResponseId, metadata, ...fields } = rest;
  const body = { input, stream, ...fields };
  if (previousResponseId) body.previous_response_id = previousResponseId;
  if (harnessId || metadata) body.metadata = { ...(metadata || {}), ...(harnessId ? { harness_id: harnessId } : {}) };
  return body;
}

async function toError(res) {
  let payload = null;
  try {
    payload = await res.json();
  } catch {
    payload = null;
  }
  const error = payload && payload.error ? payload.error : {};
  return new UhpError({
    status: res.status,
    type: error.type,
    code: error.code,
    message: error.message || `request failed with ${res.status}`,
    param: error.param ?? null,
    detail: error.detail ?? null,
    requestId: res.headers.get('x-request-id'),
  });
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export { PROTOCOL_VERSION, TaskAccumulator, outputText, artifacts, idempotencyKey, isTerminal };
export default HarnessRouter;
